import{Z as i,e as a,f as n,a0 as s}from"./chunks/framework.DmpHOl9T.js";const t="/assets/synced-field.BZf7EgyF.png",y=JSON.parse('{"title":"Synced Fields","description":"","frontmatter":{},"headers":[],"relativePath":"forms/synced-fields.md","filePath":"forms/synced-fields.md","lastUpdated":1782353925000}'),d={name:"forms/synced-fields.md"};function o(l,e,r,c,h,f){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="synced-fields" tabindex="-1">Synced Fields <a class="header-anchor" href="#synced-fields" aria-label="Permalink to &quot;Synced Fields&quot;">​</a></h1><p>Synced fields let you reuse the same field definition across multiple forms.</p><p>They are useful when a field should stay consistent everywhere it appears, instead of becoming a separate copy in each form. When a field is added as a synced field, Formie links it to the original field, so changes made to one instance are reflected everywhere that synced field is used.</p><p>This is especially useful for fields that appear repeatedly across a site, such as email addresses, phone numbers, consent checkboxes, and other common contact details.</p><h2 id="when-to-use-synced-fields" tabindex="-1">When to Use Synced Fields <a class="header-anchor" href="#when-to-use-synced-fields" aria-label="Permalink to &quot;When to Use Synced Fields&quot;">​</a></h2><p>Synced fields are a good fit when:</p><ul><li>the field should behave the same way in every form</li><li>you want one change to update every use of that field</li><li>you are trying to avoid duplicated maintenance</li></ul><p>They are a poor fit when a field only looks similar but needs to drift over time. In that case, a normal copied field is usually the better choice.</p><h2 id="adding-a-synced-field" tabindex="-1">Adding a Synced Field <a class="header-anchor" href="#adding-a-synced-field" aria-label="Permalink to &quot;Adding a Synced Field&quot;">​</a></h2><p>In the form builder, add a field from the existing fields picker instead of creating a new one. When you choose an existing field, you can add it as a synced field so it stays linked to the original.</p><p><img src="'+t+'" alt="Synced field badge in the builder"></p><p>That same picker can also add a normal copied field instead. The difference is important:</p><ul><li>a copied field starts as a duplicate, then becomes independent</li><li>a synced field stays linked</li></ul><p>Because the field stays linked, editing it in one form means editing it everywhere. That is what makes synced fields useful, but it is also why they need a little more care.</p><h2 id="synced-fields-inside-groups" tabindex="-1">Synced Fields Inside Groups <a class="header-anchor" href="#synced-fields-inside-groups" aria-label="Permalink to &quot;Synced Fields Inside Groups&quot;">​</a></h2><p>You can add existing or synced fields inside <strong>Group</strong> fields from the form builder. This is useful when you want independent group wrappers — such as delivery and invoice address blocks — that each contain the same reusable field definition.</p><p>Each group keeps its own label and settings, while synced nested fields stay linked to the shared definition. Submission values are namespaced by the group handle, for example <code>deliveryAddress.email</code> and <code>invoiceAddress.email</code>.</p><h2 id="working-with-shared-fields" tabindex="-1">Working with Shared Fields <a class="header-anchor" href="#working-with-shared-fields" aria-label="Permalink to &quot;Working with Shared Fields&quot;">​</a></h2><p>Formie warns you about this in the builder, but it is still worth being deliberate. If you need an independent version later, the usual answer is to create a new field rather than trying to keep changing a shared one.</p><h2 id="synced-fields-in-stencils" tabindex="-1">Synced Fields in Stencils <a class="header-anchor" href="#synced-fields-in-stencils" aria-label="Permalink to &quot;Synced Fields in Stencils&quot;">​</a></h2><p>You can add synced fields while building a <a href="/forms/stencils">stencil</a>. The stencil stores the shared definition by handle so new forms created from that stencil link to the same field definition.</p><p>Project stencils resolve synced fields by handle, so the shared definition should already exist on each environment (or Formie will create an independent copy from the stencil field settings).</p><h2 id="synced-fields-and-multi-site" tabindex="-1">Synced Fields and Multi-Site <a class="header-anchor" href="#synced-fields-and-multi-site" aria-label="Permalink to &quot;Synced Fields and Multi-Site&quot;">​</a></h2><p>Synced fields store their shared label, handle, and definition settings in one global field definition. Every placement on every form points at that same definition.</p><p>On multi-site projects, <a href="/forms/multi-site-and-translation#content-translation">content translation overrides</a> still apply per <strong>field placement</strong> — keyed by each placement’s reference, not by the shared definition id. That means:</p><ul><li>editing a synced field on the form’s <strong>source site</strong> updates the shared definition, which affects every form and every site that does not have a site override for that placement</li><li>editing a synced field on a <strong>secondary site</strong> saves a site override for that placement only; the shared definition stays unchanged</li><li>if the same synced field appears twice on one form — for example inside delivery and invoice groups — each placement has its own reference, so secondary sites can translate each placement independently even though they share one definition</li></ul><p>Per-placement settings such as <strong>required</strong> remain local to each form field row. Site overrides can change translatable placement settings the same way as for normal fields.</p><p>If you need completely different labels or behaviour per site without sharing a definition, use a copied field instead of a synced one.</p>',28)])])}const u=i(d,[["render",o]]);export{y as __pageData,u as default};
